// func HashP(left *[64]uint32, right *[64]uint32, flags uint32, key *[8]uint32, out *[64]uint32, n int)
// Requires: AVX, AVX2, AVX512F, AVX512VL
TEXT ·HashP(SB), NOSPLIT, $72-48
	MOVQ left+0(FP), AX
	MOVQ right+8(FP), CX
	MOVL flags+16(FP), DX
	MOVQ key+24(FP), BX
	MOVQ out+32(FP), SI

	// Allocate local space and align it
	LEAQ 31(SP), DI
	ANDQ $-32, DI

	// Set up flags value
	MOVL DX, 64(SP)

	// Perform the rounds
	// Round 1
	VPBROADCASTD (BX), Y0
	VPADDD       (AX), Y0, Y0
	VPBROADCASTD 4(BX), Y1
	VPADDD       64(AX), Y1, Y1
	VPBROADCASTD 8(BX), Y2
	VPADDD       128(AX), Y2, Y2
	VPBROADCASTD 12(BX), Y3
	VPADDD       192(AX), Y3, Y3
	VPBROADCASTD 16(BX), Y4
	VPADDD       Y4, Y0, Y0
	VMOVDQU      zero<>+0(SB), Y5
	VPXOR        Y0, Y5, Y5
